-- 2026-06-11_06_hs_checklist_seed.sql
-- Seeds the Insurance H&S template family (design spec §5/§8). Editable afterwards in both apps.
-- Org: GMI production org. Six-monthly obligations are seeded as QUARTERLY
-- verification items (spec §3 frequency resolution — no new enum value for iOS safety).

insert into checklist_templates (id, name, description, frequency, responsible_role, is_active, organization_id, applies_to_building_types) values
  ('dddd4444-0000-4000-8000-000000000001','H&S Daily Walk','Insurance health & safety daily site walk — statutory and insurer-warranty checks','daily','user',true,(select id from organizations order by created_at asc limit 1),null),
  ('dddd4444-0000-4000-8000-000000000002','H&S Weekly Checks','Weekly fire, power, water and security system checks','weekly','user',true,(select id from organizations order by created_at asc limit 1),null),
  ('dddd4444-0000-4000-8000-000000000003','H&S Monthly Inspection','Monthly in-house inspection of fire equipment, emergency systems and OHS records','monthly','user',true,(select id from organizations order by created_at asc limit 1),null),
  ('dddd4444-0000-4000-8000-000000000004','H&S Quarterly Inspection','Quarterly service-record verification and six-monthly obligation checks','quarterly','user',true,(select id from organizations order by created_at asc limit 1),null),
  ('dddd4444-0000-4000-8000-000000000005','H&S Annual Statutory Verification','Annual verification that statutory certificates and accredited servicing are current','annually','manager',true,(select id from organizations order by created_at asc limit 1),null),
  ('dddd4444-0000-4000-8000-000000000006','H&S Retail Add-on','Retail / shopping centre specific health & safety checks','monthly','user',true,(select id from organizations order by created_at asc limit 1),array['retail','mixed_use']),
  ('dddd4444-0000-4000-8000-000000000007','H&S Industrial Add-on','Industrial / warehousing specific health & safety checks','monthly','user',true,(select id from organizations order by created_at asc limit 1),array['industrial','mixed_use'])
on conflict (id) do nothing;

insert into template_items (id, template_id, task_name, task_description, responsible_party, requires_photo, requires_signature, display_order, category) values
-- ===== T1: H&S Daily Walk =====
('dddd4444-0001-4000-8000-000000000001','dddd4444-0000-4000-8000-000000000001','Escape routes and emergency exits clear','All escape routes unobstructed; exit doors unlocked and openable from inside. Ref: Environmental Regs for Workplaces; SANS 10400-T; insurer public liability.','Operations',true,false,1,'fire_safety'),
('dddd4444-0001-4000-8000-000000000002','dddd4444-0000-4000-8000-000000000001','Fire doors closed, not wedged open','Self-closers operating; no wedges or props. Ref: SANS 10400-T.','Operations',false,false,2,'fire_safety'),
('dddd4444-0001-4000-8000-000000000003','dddd4444-0000-4000-8000-000000000001','Fire equipment access unobstructed','Extinguishers, hose reels and hydrants visible, signed and unblocked. Ref: SANS 1475 / SANS 10400-T; insurer fire warranty.','Operations',false,false,3,'fire_safety'),
('dddd4444-0001-4000-8000-000000000004','dddd4444-0000-4000-8000-000000000001','Emergency exit signage visible','Illuminated or photoluminescent signage intact on all routes. Ref: SANS 10400-T.','Operations',false,false,4,'emergency_preparedness'),
('dddd4444-0001-4000-8000-000000000005','dddd4444-0000-4000-8000-000000000001','Walkways free of slip and trip hazards','No spills, loose tiles or paving, trailing cables; wet-floor signage deployed where needed. Ref: OHS Act s8-9; insurer public liability.','Operations',true,false,5,'public_liability'),
('dddd4444-0001-4000-8000-000000000006','dddd4444-0000-4000-8000-000000000001','Refuse areas free of combustible build-up','Waste contained; nothing stored against the building or fire escapes. Ref: municipal fire bylaws; insurer fire warranty.','Cleaning Staff',false,false,6,'housekeeping'),
('dddd4444-0001-4000-8000-000000000007','dddd4444-0000-4000-8000-000000000001','Water leaks and ponding check','Plant rooms, ceilings and basements checked; leaks logged as issues. Ref: insurer water-damage mitigation.','Maintenance',false,false,7,'water_systems'),
('dddd4444-0001-4000-8000-000000000008','dddd4444-0000-4000-8000-000000000001','Access control and perimeter functional','Gates, booms and turnstiles operational; guard register signed. Ref: insurer security/burglary warranty.','Security',false,false,8,'security'),
-- ===== T2: H&S Weekly Checks =====
('dddd4444-0002-4000-8000-000000000001','dddd4444-0000-4000-8000-000000000002','Fire alarm panel healthy','Fire detection panel shows no faults or isolations. Ref: SANS 10139 maintenance regime; insurer fire warranty.','Operations',true,false,1,'fire_safety'),
('dddd4444-0002-4000-8000-000000000002','dddd4444-0000-4000-8000-000000000002','Sprinkler valves locked open, gauges in range','Control valves locked open; pressure gauges within range. Ref: ASIB rules / SANS 10287 owner routine (verify cadence with ASIB provider).','Operations',true,false,2,'fire_safety'),
('dddd4444-0002-4000-8000-000000000003','dddd4444-0000-4000-8000-000000000002','Generator test run','Test run completed; fuel, oil and battery checked; hour-meter photographed. Ref: emergency preparedness; insurer business-interruption expectations.','Maintenance',true,false,3,'electrical'),
('dddd4444-0002-4000-8000-000000000004','dddd4444-0000-4000-8000-000000000002','Emergency and exit lighting spot check','Sample of emergency/exit luminaires verified working. Ref: SANS 10400-T (verify full regime with provider).','Maintenance',false,false,4,'emergency_preparedness'),
('dddd4444-0002-4000-8000-000000000005','dddd4444-0000-4000-8000-000000000002','Geysers and plant rooms: leaks and PRV check','No leaks; pressure-relief discharge clear. Ref: insurer water-damage mitigation.','Maintenance',false,false,5,'water_systems'),
('dddd4444-0002-4000-8000-000000000006','dddd4444-0000-4000-8000-000000000002','Intruder alarm and CCTV operational','Alarm arms/disarms correctly; cameras recording. Ref: insurer security/burglary warranty (common repudiation ground).','Security',false,false,6,'security'),
-- ===== T3: H&S Monthly Inspection =====
('dddd4444-0003-4000-8000-000000000001','dddd4444-0000-4000-8000-000000000003','Extinguisher visual check incl. service labels','Each unit in place, pin and seal intact, pressure in green, service label within 12 months. Ref: SANS 1475 / SANS 10400-T; OHS Act; insurer fire warranty.','Operations',true,false,1,'fire_safety'),
('dddd4444-0003-4000-8000-000000000002','dddd4444-0000-4000-8000-000000000003','Hose reels and hydrants visual check','Hose intact, nozzle present, valves accessible and undamaged. Ref: SANS 1475 part 2 (verify).','Operations',false,false,2,'fire_safety'),
('dddd4444-0003-4000-8000-000000000003','dddd4444-0000-4000-8000-000000000003','Emergency lighting function test','Function test via test facility or simulated mains failure. Ref: SANS 10400-T.','Maintenance',false,false,3,'emergency_preparedness'),
('dddd4444-0003-4000-8000-000000000004','dddd4444-0000-4000-8000-000000000003','First-aid boxes stocked, first aiders displayed','Boxes fully stocked; first-aider names displayed. Ref: General Safety Regulation 3 (GSR 3.4 appointments).','Operations',true,false,4,'occupational_safety'),
('dddd4444-0003-4000-8000-000000000005','dddd4444-0000-4000-8000-000000000003','Electrical DB rooms clear and closed','Distribution boards closed and labelled; no storage within clearance. Ref: Electrical Installation Regulations 2009 competent-person maintenance duty.','Maintenance',true,false,5,'electrical'),
('dddd4444-0003-4000-8000-000000000006','dddd4444-0000-4000-8000-000000000003','Statutory H&S signage condition','No-smoking, assembly point and capacity signage present and legible. Ref: OHS Act; municipal bylaws.','Operations',false,false,6,'occupational_safety'),
('dddd4444-0003-4000-8000-000000000007','dddd4444-0000-4000-8000-000000000003','OHS file current','Signed appointment letters (s16(2), H&S reps, first aiders, fire fighters, GAR 9(2) incident recorder), registers and incident book up to date. Ref: OHS Act ss16-19; DPSA compliance tool evidence standard.','Operations',false,false,7,'occupational_safety'),
('dddd4444-0003-4000-8000-000000000008','dddd4444-0000-4000-8000-000000000003','Parking areas: lighting, barriers, demarcation','Lighting working; barriers and demarcation in good order. Ref: insurer public liability.','Operations',false,false,8,'public_liability'),
-- ===== T4: H&S Quarterly Inspection =====
('dddd4444-0004-4000-8000-000000000001','dddd4444-0000-4000-8000-000000000004','Sprinkler routine inspection record on file','13-weekly routine service record from provider on file. Ref: SANS 10287 (verify contract cadence with ASIB provider).','Fire Safety Contractor',true,false,1,'fire_safety'),
('dddd4444-0004-4000-8000-000000000002','dddd4444-0000-4000-8000-000000000004','HVAC / refrigeration service record current','Provider service record on file. Ref: SANS 10147 (verify).','HVAC Contractor',false,false,2,'occupational_safety'),
('dddd4444-0004-4000-8000-000000000003','dddd4444-0000-4000-8000-000000000004','Pest control service record current','Provider service record on file. Ref: R638 hygiene expectations (retail); good practice elsewhere.','Pest Control Contractor',false,false,3,'housekeeping'),
('dddd4444-0004-4000-8000-000000000004','dddd4444-0000-4000-8000-000000000004','Roof, gutters and stormwater inspection','Roof coverings, gutters and stormwater drains clear and sound. Ref: insurer storm/water-damage mitigation.','Maintenance',true,false,4,'water_systems'),
('dddd4444-0004-4000-8000-000000000005','dddd4444-0000-4000-8000-000000000004','Fire risk assessment actions reviewed','Open actions from the fire risk assessment reviewed and progressed. Ref: OHS Act s8 risk assessment duty.','Operations',false,false,5,'fire_safety'),
('dddd4444-0004-4000-8000-000000000006','dddd4444-0000-4000-8000-000000000004','Evacuation drill within last 6 months','Verify last internal evacuation drill is within 6 months; conduct and log one if due. Photograph attendance register. Ref: 6-monthly cadence (DPSA compliance tool; emergency planning under ERW).','Operations',true,false,6,'emergency_preparedness'),
('dddd4444-0004-4000-8000-000000000007','dddd4444-0000-4000-8000-000000000004','Emergency plan and emergency team current','Documented evacuation plan displayed; fire fighters, first aiders and marshals appointed and current. Ref: DPSA compliance tool.','Operations',false,false,7,'emergency_preparedness'),
